    _verified_status = f"**Qualified visible-answer acceptance:** {sum(row['outcome'] == 'passed' for row in _verified_rows)}/{len(_verified_rows)} qualified attempts passed. The table's passed column preserves native grades. Earlier revisions used unreliable asynchronous UI waits and are historical evidence; they do not establish visible-answer acceptance. Supplemental patch checks are separate qualifications."
    _reasons = [item["reason"] for item in saved.get("measurementPolicy", {}).get("exclusions", []) if project_id in ["overview", item["project"]]]
    if _reasons:
        _verified_status += "\n\n" + "\n\n".join(_reasons)
    counts = Counter((row["project"], row["variant"], row["sourceCommit"], row["outcome"]) for row in rows)
    aggregates = []
    for _project, _variant, _source in sorted({(row["project"], row["variant"], row["sourceCommit"]) for row in rows}):
        _group = [row for row in rows if (row["project"], row["variant"], row["sourceCommit"]) == (_project, _variant, _source)]
        aggregates.append({"project": _project, "variant": _variant, "source_commit": _source, "attempts": len(_group), "passed": counts[_project, _variant, _source, "passed"], "task_failed": counts[_project, _variant, _source, "task_failed"], "infrastructure_failed": counts[_project, _variant, _source, "infrastructure_failed"], "telemetry_missing": counts[_project, _variant, _source, "telemetry_missing"], "known_estimate_usd": round(sum(row.get("reconciledEstimateUsd", row.get("estimatedCostUsd")) or 0 for row in _group), 6), "unknown_cost_attempts": sum(row.get("estimatedCostUsd") is None and row.get("reconciledEstimateUsd") is None for row in _group)})
    mo.vstack([mo.md("## Saved results\n\n" + saved.get("status", "No campaign has been recorded.")), mo.md(_verified_status), mo.ui.table(aggregates, selection=None, pagination=False) if aggregates else mo.md("No trials are recorded for this project. This is an explicit absence of evidence, not a zero score."), mo.md("Target: three repeats per automated variant. Show task failures, infrastructure failures and missing telemetry separately. Repeats of one task are not independent tasks. Rows are grouped by project, treatment and source revision. Cost sums include audited reconciliations where available; unknown token usage remains unknown even when a reservation is charged conservatively. Original outcomes are preserved; see the shared ledger for reservations and reconciliation evidence."), mo.ui.table(rows, selection=None) if rows else mo.md("No run rows to display."), mo.md("### Qualification and budget evidence"), mo.ui.table(saved.get("qualifications", []), selection=None), mo.md("```json\n" + __import__("json").dumps({key: value for key, value in saved.get("budget", {}).items() if key != "settled"}, indent=2) + "\n```")])
